const INF = 1e20;
function edt1d(f, n, d, v, z) {
  let k = 0;
  v[0] = 0;
  z[0] = -INF;
  z[1] = INF;
  for (let q = 1; q < n; q++) {
    let s = (f[q] + q * q - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k]);
    while (s <= z[k]) {
      k--;
      s = (f[q] + q * q - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k]);
    }
    k++;
    v[k] = q;
    z[k] = s;
    z[k + 1] = INF;
  }
  k = 0;
  for (let q = 0; q < n; q++) {
    while (z[k + 1] < q) k++;
    d[q] = (q - v[k]) * (q - v[k]) + f[v[k]];
  }
}
/** Squared euclidean distance transform; grid: 0 at features, INF elsewhere. */
function edt2d(grid, w, h) {
  const n = Math.max(w, h);
  const f = new Float64Array(n),
    d = new Float64Array(n),
    z = new Float64Array(n + 1);
  const v = new Int32Array(n);
  for (let x = 0; x < w; x++) {
    for (let y = 0; y < h; y++) f[y] = grid[y * w + x];
    edt1d(f, h, d, v, z);
    for (let y = 0; y < h; y++) grid[y * w + x] = d[y];
  }
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) f[x] = grid[y * w + x];
    edt1d(f, w, d, v, z);
    for (let x = 0; x < w; x++) grid[y * w + x] = d[x];
  }
}
class TerrainField {
  // world units per pixel
  // signed distance (world units), + on land
  // component index per pixel (-1 water)
  compRegion = [];
  constructor(gw = 1536) {
    this.gw = gw;
    this.gh = Math.round(gw * HEIGHT / WIDTH);
    this.px = WIDTH / gw;
    const {
      gw: W,
      gh: H
    } = this;

    // --- rasterize coastline
    const cv = document.createElement('canvas');
    cv.width = W;
    cv.height = H;
    const ctx = cv.getContext('2d', {
      willReadFrequently: true
    });
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = '#fff';
    const rings = coastData;
    for (const r of rings) {
      ctx.beginPath();
      r.forEach(([lon, lat], i) => {
        const [x, z] = project(lat, lon);
        const cx = (x + WIDTH / 2) / WIDTH * W;
        const cy = (z + HEIGHT / 2) / HEIGHT * H;
        if (i === 0) ctx.moveTo(cx, cy);else ctx.lineTo(cx, cy);
      });
      ctx.closePath();
      ctx.fill();
    }
    const img = ctx.getImageData(0, 0, W, H).data;
    const land = new Uint8Array(W * H);
    for (let i = 0; i < W * H; i++) land[i] = img[i * 4] > 127 ? 1 : 0;

    // --- signed distance
    const gL = new Float64Array(W * H),
      gW = new Float64Array(W * H);
    for (let i = 0; i < W * H; i++) {
      gL[i] = land[i] ? INF : 0; // distance from land px to water
      gW[i] = land[i] ? 0 : INF; // distance from water px to land
    }

    edt2d(gL, W, H);
    edt2d(gW, W, H);
    this.sd = new Float32Array(W * H);
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        const i = y * W + x;
        let d = land[i] ? Math.sqrt(gL[i]) - 0.5 : -(Math.sqrt(gW[i]) - 0.5);
        d *= this.px;
        // organic coastline perturbation
        if (Math.abs(d) < 2.2) {
          const wx = x / W * WIDTH,
            wz = y / H * HEIGHT;
          d += fbm(wx * 0.55, wz * 0.55, 3) * 0.32 * (1 - smoothstep(0.8, 2.2, Math.abs(d)));
        }
        this.sd[i] = d;
      }
    }

    // --- connected components of land
    this.comp = new Int32Array(W * H).fill(-1);
    const stack = new Int32Array(W * H);
    let nc = 0;
    for (let i = 0; i < W * H; i++) {
      if (this.sd[i] <= 0 || this.comp[i] >= 0) continue;
      let sp = 0,
        size = 0,
        sy = 0,
        sx = 0;
      stack[sp++] = i;
      this.comp[i] = nc;
      while (sp) {
        const c = stack[--sp];
        size++;
        sy += c / W | 0;
        const cx = c % W;
        sx += cx;
        const nb = [c - 1, c + 1, c - W, c + W];
        for (let k = 0; k < 4; k++) {
          const nIdx = nb[k];
          if (nIdx < 0 || nIdx >= W * H) continue;
          if (k === 0 && cx === 0 || k === 1 && cx === W - 1) continue;
          if (this.sd[nIdx] > 0 && this.comp[nIdx] < 0) {
            this.comp[nIdx] = nc;
            stack[sp++] = nIdx;
          }
        }
      }
      const cyWorld = sy / size / H * HEIGHT - HEIGHT / 2;
      const cxWorld = sx / size / W * WIDTH - WIDTH / 2;
      const [lat, lon] = unproject(cxWorld, cyWorld);
      this.compRegion[nc] = size > 40000 ? lat > 26.2 ? 'iran' : 'arabia' : lon < 50.85 && lat < 26.0 ? 'arabia' : 'island';
      nc++;
    }

    // --- texture for water shader (R coarse ±16, G fine ±2)
    const tex = new Uint8Array(W * H * 4);
    for (let i = 0; i < W * H; i++) {
      const d = this.sd[i];
      tex[i * 4] = Math.round(clamp(d / 16 * 0.5 + 0.5, 0, 1) * 255);
      tex[i * 4 + 1] = Math.round(clamp(d / 2 * 0.5 + 0.5, 0, 1) * 255);
      tex[i * 4 + 2] = 0;
      tex[i * 4 + 3] = 255;
    }
    this.sdTexture = new THREE.DataTexture(tex, W, H, THREE.RGBAFormat);
    this.sdTexture.magFilter = THREE.LinearFilter;
    this.sdTexture.minFilter = THREE.LinearFilter;
    this.sdTexture.flipY = false;
    this.sdTexture.needsUpdate = true;
  }
  toPix(x, z) {
    return [(x + WIDTH / 2) / WIDTH * this.gw - 0.5, (z + HEIGHT / 2) / HEIGHT * this.gh - 0.5];
  }
  sample(x, z) {
    const [fx, fy] = this.toPix(x, z);
    const x0 = clamp(Math.floor(fx), 0, this.gw - 2),
      y0 = clamp(Math.floor(fy), 0, this.gh - 2);
    const tx = clamp(fx - x0, 0, 1),
      ty = clamp(fy - y0, 0, 1);
    const i = y0 * this.gw + x0;
    const s = this.sd;
    return (s[i] * (1 - tx) + s[i + 1] * tx) * (1 - ty) + (s[i + this.gw] * (1 - tx) + s[i + this.gw + 1] * tx) * ty;
  }
  region(x, z) {
    const [fx, fy] = this.toPix(x, z);
    const i = clamp(Math.round(fy), 0, this.gh - 1) * this.gw + clamp(Math.round(fx), 0, this.gw - 1);
    const c = this.comp[i];
    return c < 0 ? 'sea' : this.compRegion[c];
  }

  /** Terrain height (world units, vertically exaggerated). */
  height(x, z) {
    const d = this.sample(x, z);
    const edge = smoothstep(0, 8, Math.min(x + WIDTH / 2, WIDTH / 2 - x, z + HEIGHT / 2, HEIGHT / 2 - z));
    if (d <= 0) return -0.12 - 2.6 * smoothstep(0, 9, -d);
    let reg = this.region(x, z);
    if (reg === 'sea') reg = 'island';
    const [lat, lon] = unproject(x, z);
    let h = 0.05 + 0.18 * smoothstep(0, 1.0, d);
    const hn = fbm(x * 0.11 + 3.1, z * 0.11 - 1.7, 4) * 0.5 + 0.5;
    if (reg === 'iran') {
      h += hn * hn * 0.7 * smoothstep(0.3, 4, d);
      const r = ridged(x * 0.028 + 10, z * 0.075 + 4, 6);
      const big = 0.25 + 0.75 * smoothstep(-0.45, 0.5, fbm(x * 0.014 + 5, z * 0.014, 3));
      const r2 = ridged(x * 0.05 - 3, z * 0.05 + 8, 5);
      h += 7.0 * smoothstep(3, 30, d) * (r * 0.6 + r2 * 0.55) * big;
    } else if (reg === 'arabia') {
      const wM = smoothstep(55.82, 56.02, lon);
      const r = ridged(x * 0.075 + 2, z * 0.075 - 5, 6);
      const mount = 4.6 * smoothstep(0.2, 5, d) * r * (0.7 + 0.3 * hn);
      const dunes = 0.18 * smoothstep(0.5, 4, d) * (Math.abs(simplex2(x * 0.35, z * 0.9)) + hn);
      h += wM * mount + (1 - wM) * dunes;
    } else {
      // islands
      h += hn * hn * 1.0 * smoothstep(0.3, 3.5, d);
      // Hormuz salt dome
      const [hx, hz] = project(26.94, 56.53);
      const rr = (x - hx) ** 2 + (z - hz) ** 2;
      h += 0.9 * Math.exp(-rr / 6) * (0.7 + 0.6 * ridged(x * 0.6, z * 0.6, 3));
      if (lat > 26.25 && lat < 26.85 && lon > 55.05 && lon < 56.25) {
        h += 0.9 * smoothstep(0.8, 5, d) * ridged(x * 0.12, z * 0.12, 4);
      }
    }
    return h * edge + 0.05 * (1 - edge);
  }
  isLand(x, z) {
    return this.sample(x, z) > 0;
  }

  /** Snap to nearest pixel matching criteria (land: coastal band; sea: deep enough water). */
  snap(x, z, kind, range = 16) {
    const curSd = this.sample(x, z);
    if (kind === 'land' && curSd > 0.38 && curSd < 6.5) return [x, z];
    if (kind === 'sea' && curSd < -1.3) return [x, z];
    const [fx, fy] = this.toPix(x, z);
    const cx = Math.round(fx),
      cy = Math.round(fy);
    let best = null;
    let bd = Infinity;
    for (let dy = -range; dy <= range; dy++) {
      for (let dx = -range; dx <= range; dx++) {
        const px = cx + dx,
          py = cy + dy;
        if (px < 0 || py < 0 || px >= this.gw || py >= this.gh) continue;
        const s = this.sd[py * this.gw + px];
        const ok = kind === 'land' ? s > 0.42 && s < 3.2 : s < -1.4;
        if (!ok) continue;
        const dd = dx * dx + dy * dy;
        if (dd < bd) {
          bd = dd;
          best = [px, py];
        }
      }
    }
    if (!best) return [x, z];
    return [(best[0] + 0.5) / this.gw * WIDTH - WIDTH / 2, (best[1] + 0.5) / this.gh * HEIGHT - HEIGHT / 2];
  }
}

// ---------------------------------------------------------------- terrain mesh
function hex(c) {
  return new THREE.Color(c);
}
const C = {
  sand: hex('#e6d3a3'),
  wetSand: hex('#c8b48a'),
  plain: hex('#cdb286'),
  desert: hex('#d9b47c'),
  rock: hex('#9a7a58'),
  darkRock: hex('#6b5443'),
  peak: hex('#bfae95'),
  hormuzRed: hex('#a9412b'),
  hormuzOchre: hex('#d0913c'),
  hormuzPurple: hex('#7e5d6a'),
  qeshm: hex('#c3a77c'),
  qeshmGrey: hex('#988a7a'),
  green: hex('#5f7d3c'),
  mangrove: hex('#3f6b3a'),
  musandam: hex('#8b725f'),
  musandamDark: hex('#5f4c40')
};
function buildTerrainMesh(field, segX = 768) {
  const segZ = Math.round(segX * HEIGHT / WIDTH);
  const geo = new THREE.PlaneGeometry(WIDTH, HEIGHT, segX, segZ);
  geo.rotateX(-Math.PI / 2);
  const pos = geo.attributes.position;
  const n = pos.count;
  const sds = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    const x = pos.getX(i),
      z = pos.getZ(i);
    pos.setY(i, field.height(x, z));
    sds[i] = field.sample(x, z);
  }
  geo.computeVertexNormals();
  const nor = geo.attributes.normal;
  const colors = new Float32Array(n * 3);
  const col = new THREE.Color();
  const [mx, mz] = project(26.72, 55.62);
  const [mnx, mnz] = project(27.1, 57.05);
  const [hx, hz] = project(26.94, 56.53);
  for (let i = 0; i < n; i++) {
    const x = pos.getX(i),
      y = pos.getY(i),
      z = pos.getZ(i);
    const d = sds[i];
    const slope = 1 - nor.getY(i);
    const reg = field.region(x, z);
    const nz = fbm(x * 0.4, z * 0.4, 3);
    const nz2 = fbm(x * 0.05 + 7, z * 0.05, 3);
    if (d <= 0.05) {
      col.copy(C.wetSand).lerp(hex('#8fae9e'), smoothstep(0, -1.2, d));
    } else if (reg === 'island' && (x - hx) ** 2 + (z - hz) ** 2 < 65) {
      const t = nz * 0.5 + 0.5;
      col.copy(C.hormuzRed).lerp(C.hormuzOchre, smoothstep(0.35, 0.7, t));
      col.lerp(C.hormuzPurple, smoothstep(0.55, 0.9, fbm(x * 1.3, z * 1.3, 2) * 0.5 + 0.5) * 0.6);
      col.lerp(C.sand, 1 - smoothstep(0.2, 0.7, d));
    } else if (reg === 'island') {
      col.copy(C.qeshm).lerp(C.qeshmGrey, smoothstep(0.05, 0.3, slope) * 0.8 + nz * 0.15);
      col.lerp(C.sand, 1 - smoothstep(0.25, 0.9, d));
    } else if (reg === 'arabia') {
      const [lat, lon] = [0, 0];
      void lat;
      void lon;
      const mountain = smoothstep(0.4, 1.6, y);
      col.copy(C.desert).lerp(hex('#e6c48e'), nz * 0.5 + 0.5);
      const rock = C.musandam.clone().lerp(C.musandamDark, smoothstep(0.1, 0.45, slope));
      col.lerp(rock, mountain);
      col.lerp(C.sand, 1 - smoothstep(0.25, 0.9, d));
    } else {
      // iran mainland
      const mountain = smoothstep(0.7, 2.6, y);
      col.copy(C.plain).lerp(C.desert, nz2 * 0.5 + 0.5);
      const rock = C.rock.clone().lerp(C.darkRock, smoothstep(0.12, 0.5, slope));
      col.lerp(rock, mountain);
      col.lerp(C.peak, smoothstep(4.5, 7, y) * 0.7);
      col.lerp(C.sand, 1 - smoothstep(0.25, 1.0, d));
      // palm groves around Minab
      const gm = Math.exp(-((x - mnx) ** 2 + (z - mnz) ** 2) / 30);
      col.lerp(C.green, gm * smoothstep(0.1, 0.6, nz * 0.5 + 0.5 + 0.3));
    }
    // Hara mangrove forest
    const mg = Math.exp(-((x - mx) ** 2 + (z - mz) ** 2) / 60);
    if (mg > 0.05 && d > -0.1 && d < 1.6) col.lerp(C.mangrove, mg * smoothstep(-0.2, 0.4, nz + 0.2));
    col.multiplyScalar(0.92 + nz * 0.1);
    colors[i * 3] = col.r;
    colors[i * 3 + 1] = col.g;
    colors[i * 3 + 2] = col.b;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));

  // detail noise texture for close-up variation
  const nc = document.createElement('canvas');
  nc.width = nc.height = 256;
  const nctx = nc.getContext('2d');
  const nd = nctx.createImageData(256, 256);
  for (let y = 0; y < 256; y++) for (let x = 0; x < 256; x++) {
    const v = 128 + 70 * fbm(x / 22, y / 22, 4) + 25 * (Math.random() - 0.5);
    const i = (y * 256 + x) * 4;
    nd.data[i] = nd.data[i + 1] = nd.data[i + 2] = v;
    nd.data[i + 3] = 255;
  }
  nctx.putImageData(nd, 0, 0);
  const detail = new THREE.CanvasTexture(nc);
  detail.wrapS = detail.wrapT = THREE.RepeatWrapping;
  const mat = new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.96,
    metalness: 0
  });
  mat.onBeforeCompile = sh => {
    sh.uniforms.uDetail = {
      value: detail
    };
    sh.vertexShader = sh.vertexShader.replace('#include <common>', '#include <common>\nvarying vec3 vWPos;').replace('#include <worldpos_vertex>', '#include <worldpos_vertex>\nvWPos = (modelMatrix * vec4(transformed,1.0)).xyz;');
    sh.fragmentShader = sh.fragmentShader.replace('#include <common>', '#include <common>\nvarying vec3 vWPos;\nuniform sampler2D uDetail;').replace('#include <color_fragment>', `#include <color_fragment>
        float dn = texture2D(uDetail, vWPos.xz * 0.9).r * 0.6 + texture2D(uDetail, vWPos.xz * 0.11).r * 0.4;
        diffuseColor.rgb *= 0.78 + dn * 0.42;`);
  };
  const mesh = new THREE.Mesh(geo, mat);
  mesh.receiveShadow = true;
  return mesh;
}

// ---------------------------------------------------------------- water
function buildWater(field) {
  const geo = new THREE.PlaneGeometry(WIDTH, HEIGHT, 1, 1);
  geo.rotateX(-Math.PI / 2);
  const uniforms = {
    uSd: {
      value: field.sdTexture
    },
    uTime: {
      value: 0
    },
    uSunDir: {
      value: new THREE.Vector3(0.5, 0.8, 0.3).normalize()
    },
    uSunColor: {
      value: new THREE.Color('#fff4dc')
    },
    uSky: {
      value: new THREE.Color('#8ec5e8')
    },
    uNight: {
      value: 0
    },
    uStorm: {
      value: 0
    },
    uFogColor: {
      value: new THREE.Color('#0b1a2a')
    },
    uFogDensity: {
      value: 0.0016
    }
  };
  const mat = new THREE.ShaderMaterial({
    uniforms,
    vertexShader: /* glsl */`
      varying vec2 vUv; varying vec3 vWorld;
      void main(){ vUv = uv; vec4 w = modelMatrix * vec4(position,1.0); vWorld = w.xyz; gl_Position = projectionMatrix * viewMatrix * w; }
    `,
    fragmentShader: /* glsl */`
      uniform sampler2D uSd; uniform float uTime; uniform vec3 uSunDir; uniform vec3 uSunColor; uniform vec3 uSky;
      uniform float uNight; uniform float uStorm; uniform vec3 uFogColor; uniform float uFogDensity;
      varying vec2 vUv; varying vec3 vWorld;
      float sdAt(vec2 uv){ vec4 t = texture2D(uSd, uv); float c = (t.r*2.0-1.0)*16.0; float f = (t.g*2.0-1.0)*2.0; return abs(f) < 1.9 ? f : c; }
      float hash(vec2 p){ p = mod(p, 289.0); vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
      float vnoise(vec2 p){ vec2 i=floor(p), f=fract(p); f=f*f*(3.0-2.0*f);
        return mix(mix(hash(i),hash(i+vec2(1,0)),f.x), mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x), f.y); }
      vec2 waveGrad(vec2 p, float t){
        vec2 g = vec2(0.0);
        vec2 d1 = normalize(vec2(1.0,0.35)); vec2 d2 = normalize(vec2(-0.4,1.0)); vec2 d3 = normalize(vec2(0.8,-0.7)); vec2 d4 = normalize(vec2(-1.0,-0.2));
        g += d1 * cos(dot(p,d1)*2.3 + t*1.7) * 0.5;
        g += d2 * cos(dot(p,d2)*3.7 + t*2.2) * 0.35;
        g += d3 * cos(dot(p,d3)*6.1 + t*2.9) * 0.22;
        g += d4 * cos(dot(p,d4)*9.3 + t*3.6) * 0.14;
        return g;
      }
      void main(){
        float sd = sdAt(vec2(vUv.x, 1.0 - vUv.y));
        if (sd > 0.25) discard;
        vec3 V = normalize(cameraPosition - vWorld);
        float camD = length(cameraPosition - vWorld);
        float near = 1.0 - smoothstep(25.0, 160.0, camD);
        vec2 g = waveGrad(vWorld.xz, uTime) * (0.10 + 0.25*uStorm) * near;
        g += (vec2(vnoise(vWorld.xz*0.08 + uTime*0.03), vnoise(vWorld.xz*0.08 - uTime*0.03 + 9.0)) - 0.5) * 0.07;
        vec3 N = normalize(vec3(-g.x, 1.0, -g.y));
        float depth = clamp(-sd / 14.0, 0.0, 1.0);
        vec3 deep = vec3(0.025,0.17,0.30);
        vec3 mid = vec3(0.05,0.36,0.52);
        vec3 shallow = vec3(0.20,0.72,0.74);
        vec3 lagoon = vec3(0.50,0.84,0.76);
        vec3 col = mix(shallow, mid, smoothstep(0.0,0.25,depth));
        col = mix(col, deep, smoothstep(0.2,1.0,depth));
        col = mix(col, lagoon, smoothstep(-0.9, 0.0, sd) * 0.8);
        // caustic-like variation in shallow water
        float caus = vnoise(vWorld.xz*1.6 + vec2(uTime*0.4, -uTime*0.3)) * vnoise(vWorld.xz*1.9 - uTime*0.25);
        col += vec3(0.10,0.16,0.14) * caus * (1.0 - smoothstep(0.0, 0.25, depth)) * near;
        // lighting
        vec3 L = normalize(uSunDir);
        float diff = clamp(dot(N, L), 0.0, 1.0);
        col *= 0.65 + 0.45*diff;
        float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 4.0);
        col = mix(col, uSky, fres * 0.55);
        vec3 H = normalize(L + V);
        float spec = pow(clamp(dot(N,H),0.0,1.0), 180.0) * 1.4 + pow(clamp(dot(N,H),0.0,1.0), 30.0)*0.12;
        col += uSunColor * spec * (1.0 - uStorm*0.8);
        // shoreline foam
        float fn = vnoise(vWorld.xz*3.0 + uTime*0.5);
        float foamLine = smoothstep(-0.28, -0.02, sd);
        float band = smoothstep(0.6, 1.0, sin(sd*9.0 + uTime*1.8 + fn*3.0)) * smoothstep(-1.4, -0.2, sd) * near;
        float foam = clamp(foamLine*0.85 + band*0.45*fn, 0.0, 1.0);
        col = mix(col, vec3(0.96,0.98,1.0) * (0.55 + 0.45*diff), foam);
        // whitecaps in storm
        col += vec3(0.6) * smoothstep(0.82, 0.95, vnoise(vWorld.xz*2.2 + uTime*1.2)) * uStorm * near;
        // night
        col = mix(col, col * vec3(0.2,0.26,0.42) + vec3(0.0,0.015,0.04), uNight);
        col = mix(col, col * 0.55 + vec3(0.03,0.05,0.07), uStorm * 0.5);
        // map border fade
        float e = min(min(vUv.x, 1.0 - vUv.x), min(vUv.y, 1.0 - vUv.y));
        col = mix(uFogColor * 1.2, col, smoothstep(0.0, 0.025, e));
        float fogF = 1.0 - exp(-uFogDensity*uFogDensity*camD*camD);
        col = mix(col, uFogColor, clamp(fogF, 0.0, 1.0));
        float alpha = 1.0 - smoothstep(0.05, 0.25, sd);
        gl_FragColor = vec4(col, alpha);
      }
    `,
    transparent: true
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.renderOrder = -1;
  return {
    mesh,
    uniforms
  };
}

